#include <unistd.h>
#include <stdio.h>
#include <string.h>

void print_message(const char* message) {
    write(STDOUT_FILENO, message, sizeof(char) * strlen(message));
}

int main() {
    const char* test_message = "Hello, World!";
    print_message(test_message);
    return 0;
}

